// Restaurant-local opening hours. Missing schedules remain unrestricted for compatibility.
const WEEKDAYS=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const timeMinutes=value=>{const match=/^(\d{1,2}):(\d{2})$/.exec(String(value||''));if(!match)return null;const h=Number(match[1]),m=Number(match[2]);return h<24&&m<60?h*60+m:null};
function branchOpeningStatus(branch,now=Date.now()){
 if(!branch)return {closed:false};
 if(branch.available===false||branch.active===false)return {closed:true,next:null};
 const schedule=branch.schedule||branch.openingHours;
 // A legacy single hours object is supported; no schedule means do not block existing orders.
 const legacy=branch.hours?.open&&branch.hours?.close?branch.hours:null;
 if(!schedule&&!legacy)return {closed:false};
 const local=new Date(new Date(now).toLocaleString('en-US',{timeZone:'Europe/Warsaw'}));
 const day=local.getDay(),minute=local.getHours()*60+local.getMinutes();
 const daySlot=index=>{
  const raw=schedule?(Array.isArray(schedule)?schedule[index]:schedule[WEEKDAYS[index]]||schedule[WEEKDAYS[index].slice(0,3)]):legacy;
  if(!raw||raw.closed===true||raw.isClosed===true||raw.enabled===false||raw.open===false)return null;
  const open=timeMinutes(raw.openTime||raw.open||raw.from||raw.start);
  const close=timeMinutes(raw.closeTime||raw.close||raw.to||raw.end);
  if(open===null||close===null||open===close)return null;
  return {open,close};
 };
 const today=daySlot(day),yesterday=daySlot((day+6)%7);
 const opened=Boolean((today&&(today.close>today.open?minute>=today.open&&minute<today.close:minute>=today.open))||(yesterday&&yesterday.close<yesterday.open&&minute<yesterday.close));
 if(opened)return {closed:false};
 for(let offset=0;offset<8;offset++){
  const slot=daySlot((day+offset)%7);if(!slot)continue;
  if(offset===0&&slot.open<=minute)continue;
  const weekday=WEEKDAYS[(day+offset)%7];
  return {closed:true,next:{weekday,offset,time:`${String(Math.floor(slot.open/60)).padStart(2,'0')}:${String(slot.open%60).padStart(2,'0')}`}};
 }
 return {closed:true,next:null};
}
