 function chooseOption(group,id){setDraft(old=>{const before=old.selections[group.id]||[];const next=before.includes(id)?(before.length>group.min?before.filter(x=>x!==id):before):(group.max===1?[id]:(before.length<group.max?[...before,id]:before));return {...old,selections:{...old.selections,[group.id]:next}}})}
