 async function placeOrder(e){e.preventDefault();if(!termsAccepted){setError(lang==='pl'?'Zaakceptuj regulamin, aby złożyć zamówienie.':lang==='uk'?'Прийміть умови, щоб оформити замовлення.':'Please accept the Terms and Conditions to place your order.');return;}if(branchOpeningStatus(branch).closed){setError(closedCopy.title);setPage('cart');return}if(!cart.length||submitting||!branchId||(orderType==='delivery'&&(!deliveryQuote?.eligible||!deliveryQuote?.quoteToken))){setError(orderType==='pickup'?'Please review your pickup order.':'Verify your delivery address before ordering.');return;}setSubmitting(true);setError('');try{const key=crypto.randomUUID();const payload={branchId,orderType,customer:{...customer,address:orderType==='pickup'?'':deliveryQuote.formattedAddress},...(orderType==='delivery'?{deliveryQuoteToken:deliveryQuote.quoteToken}:{}),paymentMethod:payment,items:cart.map(i=>({productId:i.productId,quantity:i.quantity,selections:i.selections,instructions:i.instructions})),idempotencyKey:key,redeemReward:redeemDiscount>0,redeemRewardCount:redeemDiscount>0?activeCredits:undefined};const result=await api('/orders',{method:'POST',headers:accountToken?{Authorization:'Bearer '+accountToken}:{},body:JSON.stringify(payload)});setLastRewardEstimate(accountToken?bestOffer(Number(result.data.subtotal||0)+Number(result.data.vatTotal||0)):null);setLastOrder(result.data);if(result.data.rewardDiscount){setRedeemable(Math.max(0,redeemable-Number(result.data.rewardDiscount)));setRewardCredits(credits=>credits.slice(activeCredits));setRedeemCount(null)}const next=[{id:result.data.id,orderNumber:result.data.orderNumber,orderType:result.data.orderType||orderType,branchId,total:result.data.total,createdAt:result.data.createdAt,status:result.data.status,trackingToken:result.data.trackingToken},...orders];setOrders(next);localStorage.setItem('dk_api_orders',JSON.stringify(next));localStorage.setItem('dk_eta_'+result.data.id,String(Date.parse(result.data.createdAt)||Date.now()));setCart([]);setDeliveryQuote(null);setOrderType('delivery');navigate('success')}catch(e){setError(e.message)}finally{setSubmitting(false)}}
